#nullable enable // autogenerated

using MukioI18n;
using MVZ2.GameContent.Damages;
using MVZ2.GameContent.Effects;
using MVZ2.GameContent.Predicators;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Definitions;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Localization;
using MVZ2.Vanilla.RandomChina;
using MVZ2Logic.Entities;
using MVZ2Logic.Level;
using PVZEngine.Damages;
using PVZEngine.Entities;
using PVZEngine.Tools;
using PVZEngine.Tools.Random;
using UnityEngine;

namespace MVZ2.GameContent.RandomChinaEvents
{
    [RandomChinaEventDefinition(VanillaRandomChinaEventNames.death)]
    public class DeathEvent : RandomChinaEventDefinition
    {
        public DeathEvent(string nsp, string path) : base(nsp, path, NAME, DESCRIPTION)
        {
        }
        public override void Run(Entity contraption, RandomGenerator rng)
        {
            var level = contraption.Level;
            using var entitiesItem = ListPool<Entity>.Rent();
            var entities = entitiesItem.Value;
            level.FindEntitiesNonAlloc(VanillaPredicators.enemy, entities);
            var effects = new DamageEffectList(VanillaDamageEffects.IGNORE_ARMOR, VanillaDamageEffects.MUTE);
            foreach (var enemy in entities)
            {
                enemy.TakeDamage(500, effects, contraption);
                var particleParam = enemy.GetSpawnParams();
                particleParam.SetProperty(EngineEntityProps.TINT, Color.black);
                particleParam.SetProperty(EngineEntityProps.DISPLAY_SCALE, Vector3.one * 3);
                enemy.Spawn(VanillaEffectID.bloodParticles, enemy.GetCenter(), particleParam);
            }
            level.ShakeScreen(15, 0, 30);
            contraption.PlaySound(VanillaSoundID.deathTarot);
        }
        [TranslateMsg("随机瓷器事件名称", VanillaStrings.CONTEXT_RANDOM_CHINA_EVENT_NAME)]
        public const string NAME = "XIII-死神";
        [TranslateMsg("随机瓷器事件描述", VanillaStrings.CONTEXT_RANDOM_CHINA_EVENT_DESCRIPTION)]
        public const string DESCRIPTION = "对所有敌人造成500点穿甲伤害";
    }
}
